{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"LA RSO annual allowable rent increase","requirement":"Rent may rise only once every 12 months by LAHD's allowable annual percentage; larger increases need LAHD approval, and market rate may be charged after vacancy or a tenant buyout. From February 2, 2026, no utility add-on is allowed.","key_value":"once every 12 months; allowable percentage set by LAHD","coverage_conditions":"Rental properties in the City of Los Angeles first built on or before October 1, 1978, plus replacement units under LAMC Section 151.28, including apartments, duplexes, ADUs, JADUs, mobile homes and hotel rooms rented 30+ days.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Replacement units under LAMC Section 151.28; ADUs, JADUs, mobile homes, rooms in hotels/rooming houses occupied more than 30 consecutive days"},"exemptions":"Rent amount not regulated for condominium or townhome tenancies commenced after December 31, 1995; luxury exemption available for units whose monthly rent on or before May 31, 1978 met the threshold.","penalty":null,"effective_date":"2026-02-02","citation":"L.A. Rent Stabilization Ordinance (RSO)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage (click here to view the allowable rent increase PDF). Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"LA RSO legal reasons for eviction","requirement":"A landlord may evict only for the listed at-fault or no-fault reasons, must file every termination notice with LAHD within three business days of service, and must pay relocation assistance for no-fault evictions.","key_value":"3 business days to file notice; relocation assistance for no-fault evictions","coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance, i.e. properties first built on or before October 1, 1978, plus replacement units under LAMC Section 151.28.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Los Angeles Municipal Code § 151.09","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant per Los Angeles Municipal Code 151.09.C.9 & 165.05.B.5.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
